def is_palindrome(s):
    c = ''.join(ch.lower() for ch in s if ch.isalnum())
    return c == c[::-1]

def get_primes(n):
    for num in range(2, n + 1):
        if all(num % i != 0 for i in range(2, int(num**0.5) + 1)):
            yield num

def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in seen: return [seen[diff], i]
        seen[num] = i
    return []

def is_balanced(s):
    stack = []
    for ch in s:
        if ch == '(': stack.append(ch)
        elif ch == ')':
            if not stack: return False
            stack.pop()
    return len(stack) == 0

